package cn.zhuatech.rpa.service;import jakarta.validation.constraints.*;import org.springframework.stereotype.Service;import java.util.*;
@Service public class BotProductionReleaseService{public Assessment assess(Request r){List<String>b=new ArrayList<>(),a=new ArrayList<>();if(!r.credentialsInVault())b.add("机器人凭据未存入凭据库");if(!r.segregationOfDutiesMet())b.add("开发、审批与生产发布未职责分离");if(r.testCoveragePercent()<80)b.add("自动化测试覆盖率低于 80%");if(!r.rollbackTested())b.add("回滚方案未验证");if(!r.dataAccessApproved())b.add("机器人数据访问权限未批准");if(!r.ownerAssigned())b.add("未指定业务与运维责任人");if(!b.isEmpty()){a.add("阻断生产发布并补齐安全、测试和治理控制");return new Assessment(Decision.BLOCKED,b,a);}if(!r.idempotencyVerified()||!r.monitoringAndAlertingReady()||r.expectedExceptionRatePercent()>5){if(!r.idempotencyVerified())a.add("验证重复执行不会造成重复业务结果");if(!r.monitoringAndAlertingReady())a.add("配置运行监控、告警和熔断");if(r.expectedExceptionRatePercent()>5)a.add("先在受控范围试运行并降低异常率");return new Assessment(Decision.PILOT,b,a);}a.add("批准生产发布并冻结包、配置、权限和回滚版本");return new Assessment(Decision.DEPLOY,b,a);}public record Request(@NotBlank String botRelease,boolean credentialsInVault,boolean segregationOfDutiesMet,@Min(0)@Max(100)int testCoveragePercent,boolean rollbackTested,boolean dataAccessApproved,boolean ownerAssigned,boolean idempotencyVerified,boolean monitoringAndAlertingReady,@Min(0)int expectedExceptionRatePercent){}public record Assessment(Decision decision,List<String>blockers,List<String>actions){}public enum Decision{DEPLOY,PILOT,BLOCKED}}
